    private ResearchCatalog.Entry entry(){int i=menu.selected();return i>=0&&i<ResearchCatalog.ENTRIES.size()?ResearchCatalog.ENTRIES.get(i):null;}
    private ResearchCatalog.Stage stage(){var e=entry();if(e==null||menu.stage(menu.selected())<=0)return null;return e.stages().get(Math.min(menu.stage(menu.selected()),e.stages().size())-1);}
    private String label(String key){return Component.translatable(key).getString();}
    private String itemName(ResearchCatalog.ItemRequirement r){if(r.legacy().contains("enchanted_placeholder"))return label(r.legacy().contains("id:0s")?"equipment.thaumcraft.protection_requirement":r.legacy().contains("id:33s")?"equipment.thaumcraft.silk_requirement":r.legacy().contains("id:35s")?"equipment.thaumcraft.fortune_requirement":"infusion.thaumcraft.sharpness_requirement");if(r.id().equals("thaumcraft:curio")&&!r.aspect().isEmpty())return label("item.thaumcraft.curio."+r.aspect());var o=new JsonObject();o.addProperty("id",r.id());o.addProperty("aspect",r.aspect());var s=BookRecipes.stack(o);return s.isEmpty()?label("research.thaumcraft.process_page"):s.getHoverName().getString();}
    private String researchName(String key){var parts=key.replaceFirst("^~","").split("@",2);var e=ResearchCatalog.BY_KEY.get(parts[0]);if(e!=null)return parts.length==2?Component.translatable("research.thaumcraft.goal_stage",Component.translatable(e.name()),parts[1]).getString():label(e.name());String flag=key.replaceFirst("^!","");if(key.equals("!gotthaumonomicon"))return label("research.thaumcraft.goal.gotthaumonomicon");if(thaumcraft.crystals.CrystalAspects.COLORS.containsKey(flag))return label("tc.aspect."+flag);return Component.translatableWithFallback("research.thaumcraft.goal."+flag,flag.replace('_',' ')).getString();}
    private List<ResearchCatalog.Addendum> addenda(){var e=entry();if(e==null)return List.of();var result=new ArrayList<ResearchCatalog.Addendum>();for(int i=0;i<e.addenda().size();i++)if(menu.addendumVisible(menu.selected(),i))result.add(e.addenda().get(i));return result;}
    private String body(){
        if(!menu.validData())return label("research.thaumcraft.invalid");var e=entry();var page=stage();if(e==null)return "";
        if(page==null)return label("research.thaumcraft.parents")+" "+String.join(", ",e.parents().stream().map(this::researchName).toList());
        var prose=label(page.text());var text=new StringBuilder();
        if(menu.stage(menu.selected())<=e.stages().size()){int goal=0;
            for(var r:page.crafts())text.append(menu.requirementDone(goal++)?"✓ ":"○ ").append(label("research.thaumcraft.craft")).append(' ').append(itemName(r)).append('\n');
            for(var r:page.research())text.append(menu.requirementDone(goal++)?"✓ ":"○ ").append(label("research.thaumcraft.discover")).append(' ').append(researchName(r)).append('\n');
            for(var r:page.items())text.append(menu.requirementDone(goal++)?"✓ ":"○ ").append(label("research.thaumcraft.deliver")).append(' ').append(r.count()).append(" × ").append(itemName(r)).append('\n');
            for(var r:page.costs())text.append(menu.requirementDone(goal++)?"✓ ":"○ ").append(label("research.thaumcraft.cost")).append(' ').append(r.amount()).append(' ').append(label("research.thaumcraft.points."+r.kind().toLowerCase(Locale.ROOT))).append(" (").append(label("research.thaumcraft.category."+r.category())).append(")\n");
        }text.append("\n").append(prose);for(var a:addenda())text.append("<PAGE>").append(label("research.thaumcraft.addendum")).append("<BR>").append(label(a.text()));return text.toString();
    }
    private List<String> recipeKeys(){var p=stage();if(p==null)return List.of();var keys=new ArrayList<String>();for(var key:p.recipes())keys.addAll(BookRecipes.expand(key));for(var a:addenda())for(var key:a.recipes())for(var expanded:BookRecipes.expand(key))if(!keys.contains(expanded))keys.add(expanded);for(var r:p.crafts())if(BookRecipes.get(r.id())!=null&&!keys.contains(r.id()))keys.add(r.id());return keys;}

 public List<String> illustratedRecipes(){return List.copyOf(recipeKeys());}
 private void layoutText(){String key=body()+"\u0000"+pageWidth+":"+pageHeight;if(key.equals(pageCache))return;pageCache=key;var pages=new ArrayList<List<DrawPart>>();var page=new ArrayList<DrawPart>();pages.add(page);int y=0,limit=(int)(pageHeight/TEXT_SCALE),lineWidth=(int)(pageWidth/TEXT_SCALE);for(var part:BookMarkup.parse(body())){if(part.kind()==BookMarkup.Kind.PAGE){if(!page.isEmpty()){page=new ArrayList<>();pages.add(page);y=0;}continue;}if(part.kind()==BookMarkup.Kind.TEXT){for(var line:font.split(BookMarkup.formatted(part.text()),lineWidth)){if(y+10>limit&&!page.isEmpty()){page=new ArrayList<>();pages.add(page);y=0;}page.add(new DrawPart(line,null,y,10));y+=10;}continue;}int h=switch(part.kind()){case BREAK->8;case LINE,DIVIDER->10;case IMAGE->Math.min(limit-4,(int)(part.image().height()*part.image().scale()*Math.min(1,lineWidth/(part.image().width()*part.image().scale())))+4);default->0;};if(y+h>limit&&!page.isEmpty()){page=new ArrayList<>();pages.add(page);y=0;}page.add(new DrawPart(null,part,y,h));y+=h;}textPages=pages.stream().map(List::copyOf).toList();}
 private int textLeaves(){layoutText();return textPages.size();}
 private int leaves(){return textLeaves()+recipeKeys().size();}private int spreads(){return Math.max(1,(leaves()+1)/2);}
 public List<String> shownRecipes(){var keys=recipeKeys();var shown=new ArrayList<String>();for(int leaf=spread*2;leaf<=spread*2+1;leaf++){int i=leaf-textLeaves();if(i>=0&&i<keys.size())shown.add(keys.get(i));}return List.copyOf(shown);}
 public String currentRecipe(){var keys=shownRecipes();return keys.isEmpty()?"":keys.getFirst();}
 public boolean showingTextPart(BookMarkup.Kind kind){layoutText();for(int leaf=spread*2;leaf<=spread*2+1&&leaf<textPages.size();leaf++)if(textPages.get(leaf).stream().anyMatch(p->p.part()!=null&&p.part().kind()==kind))return true;return false;}
 protected void extractLabels(GuiGraphicsExtractor g,int x,int y){}
 private void line(GuiGraphicsExtractor g,int x1,int y1,int x2,int y2,int color){double length=Math.hypot(x2-x1,y2-y1);if(length<1)return;g.pose().pushMatrix();g.pose().translate(x1,y1);g.pose().rotate((float)Math.atan2(y2-y1,x2-x1));g.fill(0,0,(int)Math.ceil(length),1,color);g.pose().popMatrix();}
 private void atlas(GuiGraphicsExtractor g,int mx,int my){var camera=cameras[category];g.enableScissor(leftPos+3,topPos+3,leftPos+mapW-3,topPos+mapH-3);int u=Math.floorMod((int)(-camera.x()/4),256),v=Math.floorMod((int)(-camera.y()/4),256);float sampleScale=Math.min(2,768F/Math.max(mapW,mapH));g.blit(RenderPipelines.GUI_TEXTURED,Identifier.parse("thaumcraft:textures/gui/gui_research_back_"+BACKGROUNDS[category]+".png"),leftPos,topPos,u,v,mapW,mapH,Math.round(mapW*sampleScale),Math.round(mapH*sampleScale),1024,1024);
  for(int i=0;i<nodes.size();i++){var child=nodes.get(i);if(!child.visible)continue;for(var query:ResearchCatalog.ENTRIES.get(i).parents()){var parent=ResearchCatalog.BY_KEY.get(query.replaceFirst("^~","").split("@")[0]);if(parent==null)continue;var p=nodes.get(ResearchCatalog.ENTRIES.indexOf(parent));if(!menu.visible(ResearchCatalog.ENTRIES.indexOf(parent))||!parent.category().equals(ResearchCatalog.CATEGORIES.get(category)))continue;int x1=p.getX()+p.getWidth()/2,y1=p.getY()+p.getHeight()/2,x2=child.getX()+child.getWidth()/2,y2=child.getY()+child.getHeight()/2;line(g,x1,y1,x2,y2,0x806f6391);line(g,x1,y1-1,x2,y2-1,0xffc4ad80);}}
  g.disableScissor();g.blit(RenderPipelines.GUI_TEXTURED,FRAME,leftPos,topPos,48,16,mapW,3,64,16,256,256);g.blit(RenderPipelines.GUI_TEXTURED,FRAME,leftPos,topPos+mapH-3,48,16,mapW,3,64,16,256,256);g.blit(RenderPipelines.GUI_TEXTURED,FRAME,leftPos,topPos,16,48,3,mapH,16,64,256,256);g.blit(RenderPipelines.GUI_TEXTURED,FRAME,leftPos+mapW-3,topPos,16,48,3,mapH,16,64,256,256);
  g.text(font,title,leftPos,topPos-12,0xffead5a2,true);g.text(font,font.substrByWidth(Component.translatable("research.thaumcraft.category."+ResearchCatalog.CATEGORIES.get(category)),Math.max(20,mapW/2-114)).getString(),leftPos+mapW/2,topPos-12,0xffead5a2,true);g.text(font,Component.translatable("research.thaumcraft.points_short",menu.points(false,category)/16,menu.points(true,category)/32),leftPos,topPos+mapH+6,0xffead5a2,true);
 }
 private void book(GuiGraphicsExtractor g,int mx,int my){g.blit(RenderPipelines.GUI_TEXTURED,BOOK,bookX,bookY,0,0,bookW,bookH,512,362,512,512);var e=entry();if(e==null)return;int texts=textLeaves();var keys=recipeKeys();for(int side=0;side<2;side++){int leaf=spread*2+side;if(leaf>=leaves())continue;int x=bookX+Math.round(bookW*(side==0?.06F:.535F));g.enableScissor(x-1,bookY+8,x+pageWidth+1,bookY+bookH-47);if(leaf<texts){g.pose().pushMatrix();g.pose().translate(x,bookY+10);g.pose().scale(.8F,.8F);int hy=0;for(var titleLine:font.split(Component.translatable(e.name()),(int)(pageWidth/.8F))){g.text(font,titleLine,0,hy,0xff493224,false);hy+=10;}g.pose().popMatrix();g.pose().pushMatrix();g.pose().translate(x,bookY+29);g.pose().scale(.65F,.65F);g.text(font,Component.translatable("research.thaumcraft.stage",Math.min(menu.stage(menu.selected()),e.stages().size()),e.stages().size()),0,0,0xff775d43,false);g.pose().popMatrix();g.pose().pushMatrix();g.pose().translate(x,pageY);g.pose().scale(TEXT_SCALE,TEXT_SCALE);for(var part:textPages.get(leaf)){if(part.text()!=null)g.text(font,part.text(),0,part.y(),0xff382d24,false);else if(part.part().kind()==BookMarkup.Kind.IMAGE){var im=part.part().image();float factor=Math.min(1,Math.min(pageWidth/TEXT_SCALE/(im.width()*im.scale()),(part.height()-4F)/(im.height()*im.scale())));int w=Math.round(im.width()*im.scale()*factor),h=Math.round(im.height()*im.scale()*factor);g.blit(RenderPipelines.GUI_TEXTURED,Identifier.parse(im.texture()),Math.round((pageWidth/TEXT_SCALE-w)/2),part.y()+2,im.x(),im.y(),w,h,im.width(),im.height(),256,256);}else if(part.part().kind()==BookMarkup.Kind.LINE||part.part().kind()==BookMarkup.Kind.DIVIDER){boolean div=part.part().kind()==BookMarkup.Kind.DIVIDER;int w=div?140:95;g.blit(RenderPipelines.GUI_TEXTURED,BOOK,Math.round((pageWidth/TEXT_SCALE-w)/2),part.y()+2,div?28:24,div?192:184,w,6,256,256);}}g.pose().popMatrix();}else{float scale=Math.min(pageWidth/160F,(bookH-72F)/170F);g.pose().pushMatrix();g.pose().translate(x,bookY+bookH*.07F);g.pose().scale(scale,scale);recipe(g,keys.get(leaf-texts),mx,my,x,bookY+bookH*.07F,scale);g.pose().popMatrix();}g.disableScissor();g.pose().pushMatrix();g.pose().translate(x+pageWidth/2-4,bookY+bookH-44);g.pose().scale(.65F,.65F);g.text(font,Integer.toString(leaf+1),0,0,0xff775d43,false);g.pose().popMatrix();}if(animatedSpread!=spread||animatedReading!=reading){transitionAt=System.currentTimeMillis();animatedSpread=spread;animatedReading=reading;}float fade=1-Math.clamp((System.currentTimeMillis()-transitionAt)/180F,0,1);if(fade>0){g.fill(bookX+bookW/2,bookY+4,bookX+bookW-5,bookY+bookH-25,((int)(fade*110)<<24)|0xf2e5c8);int fold=bookX+bookW/2+Math.round(bookW*.47F*(1-fade));g.fill(fold-3,bookY+7,fold,bookY+bookH-27,((int)(fade*100)<<24)|0x63452b);g.fill(fold,bookY+7,fold+2,bookY+bookH-27,((int)(fade*180)<<24)|0xffefce);}}
 private void icon(GuiGraphicsExtractor g,ItemStack stack,int x,int y,int mx,int my,double ox,double oy,float scale){if(stack.isEmpty())return;g.item(stack,x,y);g.itemDecorations(font,stack,x,y);double px=ox+x*scale,py=oy+y*scale;if(mx>=px&&mx<px+16*scale&&my>=py&&my<py+16*scale)g.setTooltipForNextFrame(font,stack,mx,my);}
 private void recipe(GuiGraphicsExtractor g,String key,int mx,int my,double ox,double oy,float scale){var view=BookRecipes.get(key);if(view==null){int y=20;for(var l:font.split(Component.translatable("research.thaumcraft.process_page"),158)){g.text(font,l,0,y,0xff493224,false);y+=10;}return;}var result=BookRecipes.result(view);int yy=0;for(var l:font.split(result.getHoverName(),158)){g.text(font,l,0,yy,0xff493224,false);yy+=10;}String kind=view.get("kind").getAsString();int ky=yy+3;for(var kindLine:font.split(Component.translatable("research.thaumcraft.recipe_kind."+kind),158)){g.text(font,kindLine,0,ky,0xff775d43,false);ky+=10;}if(kind.equals("blueprint")){blueprint(g,view,mx,my,ox,oy,scale,yy+17);return;}var grid=view.getAsJsonArray("grid");for(int i=0;i<grid.size()&&i<9;i++)icon(g,BookRecipes.stack(grid.get(i)),5+(i%3)*20,40+(i/3)*20,mx,my,ox,oy,scale);g.text(font,"→",82,64,0xff775d43,false);icon(g,result,119,61,mx,my,ox,oy,scale);if(view.has("input"))icon(g,BookRecipes.stack(view.get("input")),81,40,mx,my,ox,oy,scale);
  if(view.has("vis")&&view.get("vis").getAsInt()>0)g.text(font,Component.translatable("research.thaumcraft.recipe_cost",view.get("vis").getAsInt()),5,104,0xff775d43,false);
  if(view.has("crystals")){int i=0;for(var a:thaumcraft.crafting.ArcaneRecipe.PRIMALS)if(view.getAsJsonObject("crystals").has(a)){var s=thaumcraft.crystals.CrystalContent.essence(a,view.getAsJsonObject("crystals").get(a).getAsInt());icon(g,s,5+i%6*24,120+i/6*20,mx,my,ox,oy,scale);i++;}}
  if(view.has("aspects")){int i=0;for(var cost:view.getAsJsonObject("aspects").entrySet()){int x=5+i%4*38,y=105+i/4*20;i++;g.blit(RenderPipelines.GUI_TEXTURED,Identifier.parse("thaumcraft:textures/aspects/"+cost.getKey()+".png"),x,y,0,0,14,14,32,32,0xff000000|thaumcraft.crystals.CrystalAspects.COLORS.get(cost.getKey()));g.text(font,cost.getValue().getAsString(),x+15,y+4,0xff493224,false);double px=ox+x*scale,py=oy+y*scale;if(mx>=px&&mx<px+14*scale&&my>=py&&my<py+14*scale)g.setTooltipForNextFrame(Component.translatable("tc.aspect."+cost.getKey()),mx,my);}}
  if(view.has("optional_tag")&&BookRecipes.stack(new JsonPrimitive("#"+view.get("optional_tag").getAsString())).isEmpty()){icon(g,new ItemStack(net.minecraft.world.item.Items.BARRIER),25,60,mx,my,ox,oy,scale);int uy=25;for(var line:font.split(Component.translatable("research.thaumcraft.diagram.unavailable"),158)){g.text(font,line,0,uy,0xff992f28,false);uy+=10;}}
  if(view.has("note")){int ny=kind.equals("crucible")?142:115;for(var l:font.split(Component.translatable(view.get("note").getAsString()),158)){g.text(font,l,0,ny,0xff775d43,false);ny+=10;}}
  if(kind.equals("salis_mundus")){int y=143;for(var l:font.split(Component.translatable("research.thaumcraft.recipe_returned"),158)){g.text(font,l,0,y,0xff775d43,false);y+=10;}}
 }
 private void blueprint(GuiGraphicsExtractor g,JsonObject view,int mx,int my,double ox,double oy,float scale,int y){var layers=view.getAsJsonArray("layers");var palette=view.getAsJsonObject("palette");int base=y+10,max=0;for(int n=0;n<layers.size();n++){var rows=layers.get(n).getAsJsonArray();int size=14,x0=n*53+4;g.text(font,Integer.toString(n+1),x0+14,y,0xff775d43,false);for(int z=0;z<rows.size();z++){String row=rows.get(z).getAsString();for(int x=0;x<row.length();x++){int px=x0+x*size,py=base+z*size;g.fill(px,py,px+size-1,py+size-1,0x18634d32);var item=palette.get(String.valueOf(row.charAt(x)));if(item!=null){g.pose().pushMatrix();g.pose().translate(px,py);g.pose().scale(size/16F,size/16F);icon(g,BookRecipes.stack(item),0,0,mx,my,ox+px*scale,oy+py*scale,scale*size/16F);g.pose().popMatrix();}}}max=Math.max(max,rows.size()*size);}int noteY=base+max+7;for(var line:font.split(Component.translatable(view.get("note").getAsString()),158)){g.text(font,line,0,noteY,0xff775d43,false);noteY+=10;}}
 public void extractBackground(GuiGraphicsExtractor g,int mx,int my,float partial){super.extractBackground(g,mx,my,partial);if(reading)book(g,mx,my);else{animatedReading=false;atlas(g,mx,my);}}
 private void topicIcon(GuiGraphicsExtractor g,ResearchAtlas.Topic topic,int x,int y,int size){if(topic.icons().isEmpty())return;var icon=topic.icons().get((int)(System.currentTimeMillis()/1200%topic.icons().size()));if(icon.has("texture")){int w=icon.get("width").getAsInt(),h=icon.get("height").getAsInt(),cell=Math.min(w,h),frames=Math.max(w,h)/cell,frame=(int)(System.currentTimeMillis()/160%frames);g.blit(RenderPipelines.GUI_TEXTURED,Identifier.parse(icon.get("texture").getAsString()),x,y,w>h?frame*cell:0,h>w?frame*cell:0,size,size,cell,cell,w,h);}else{var stack=BookRecipes.stack(icon);g.pose().pushMatrix();g.pose().translate(x,y);g.pose().scale(size/16F,size/16F);g.item(stack,0,0);g.pose().popMatrix();}}
 private final class ArtButton extends Button {
  final String kind;final int ref;
  ArtButton(int x,int y,int w,int h,Component text,String kind,int ref,OnPress press){super(x,y,w,h,text,press,DEFAULT_NARRATION);this.kind=kind;this.ref=ref;setTooltip(Tooltip.create(text));}
  public boolean isMouseOver(double x,double y){return (!kind.equals("node")||inside(x,y))&&super.isMouseOver(x,y);}
  protected void extractContents(GuiGraphicsExtractor g,int mx,int my,float partial){int x=getX(),y=getY(),w=getWidth(),h=getHeight();if(kind.equals("node")){g.enableScissor(leftPos+3,topPos+3,leftPos+mapW-3,topPos+mapH-3);var e=ResearchCatalog.ENTRIES.get(ref);var t=ResearchAtlas.TOPICS.get(e.key());int u=t.meta().contains("ROUND")?144:t.meta().contains("HEX")?112:80,v=t.meta().contains("HIDDEN")?80:48;g.blit(RenderPipelines.GUI_TEXTURED,FRAME,x,y,u,v,w,h,32,32,256,256);if(t.meta().contains("SPIKY"))g.blit(RenderPipelines.GUI_TEXTURED,FRAME,x,y,176,v,w,h,32,32,256,256);topicIcon(g,t,x+w/4,y+h/4,w/2);if(menu.stage(ref)>e.stages().size())g.text(font,"✓",x+w-7,y+h-9,0xff7be289,true);else if(menu.stage(ref)>0)g.fill(x+w/2-2,y+h-3,x+w/2+2,y+h-1,0xfff8d27b);if(isHovered){int alpha=35+(int)(15*Math.sin(System.currentTimeMillis()/150D));g.fill(x+3,y+3,x+w-3,y+h-3,(alpha<<24)|0xffe6b2);g.fill(x+4,y+h-1,x+w-4,y+h,0xffebd49c);}g.disableScissor();return;}
   if(kind.equals("tab")){g.blit(RenderPipelines.GUI_TEXTURED,FRAME,x,y,80,ref==category?80:48,w,h,32,32,256,256);String tex=ref==0?"textures/items/thaumonomicon_cheat.png":"textures/research/cat_"+ResearchCatalog.CATEGORIES.get(ref).toLowerCase(Locale.ROOT)+".png";g.blit(RenderPipelines.GUI_TEXTURED,Identifier.parse("thaumcraft:"+tex),x+6,y+6,0,0,16,16,32,32);return;}
   if(kind.equals("previous")||kind.equals("next")||kind.equals("back")){if(!active)return;g.blit(RenderPipelines.GUI_TEXTURED,BOOK,x,y,kind.equals("next")?320:80,kind.equals("next")?448:408,w,h,kind.equals("next")?16:24,16,512,512);return;}
   if(kind.equals("recipes")||kind.equals("advance")||kind.equals("search"))g.blit(RenderPipelines.GUI_TEXTURED,BOOK,x,y,168,432,w,h,126,22,512,512);
   int color=reading?(active?0xff67341f:0xff9c8972):0xffead5a2;g.pose().pushMatrix();g.pose().translate(x,y+(h-7)/2F);g.pose().scale(.8F,.8F);String caption=font.substrByWidth(getMessage(),(int)((w-6)/.8F)).getString();g.text(font,caption,Math.round((w/.8F-font.width(caption))/2),0,color,!reading);g.pose().popMatrix();if(isHovered&&active)g.fill(x,y+h-1,x+w,y+h,reading?0xff9c6441:0xffead5a2);
  }
 }
